68	// loadRepoSessions returns the most recent sessions whose checkpoints are reachable
69	// from the default branch. Returns nil silently on any error.
70	func loadRepoSessions(ctx context.Context) []insightsdb.SessionRow {
71		repoCheckpoints := buildRepoCheckpointSet(ctx)
72		if len(repoCheckpoints) == 0 {
73			return nil
74		}
75		worktreeRoot, err := paths.WorktreeRoot(ctx)
76		if err != nil {
77			return nil
78		}
79		idb, err := insightsdb.Open(filepath.Join(worktreeRoot, paths.EntireDir, "insights.db"))
80		if err != nil {
81			return nil
82		}
83		defer func() { _ = idb.Close() }()
84	
85		ids := make([]string, 0, len(repoCheckpoints))
86		for id := range repoCheckpoints {
87			ids = append(ids, id)
88		}
89		rows, err := idb.QueryByCheckpointIDs(ctx, ids, maxSummaryRecentSessions)
90		if err != nil {
91			return nil
92		}
93		return rows
94	}
