267	func renderSummaryText(w io.Writer, rows []insightsdb.SessionRow) {
268		s := termstyle.New(w)
269		fmt.Fprintln(w, s.Render(s.Bold, "Session Summary"))
270		if len(rows) == 0 {
271			fmt.Fprintln(w, "No sessions found.")
272			return
273		}
274	
275		for _, row := range rows {
276			fmt.Fprintf(w, "\n%s  %s  %s\n", row.CreatedAt.Format("2006-01-02 15:04"), row.Agent, row.SessionID)
277			if row.OwnerID != "" || row.OwnerName != "" || row.OwnerEmail != "" {
278				fmt.Fprintf(w, "Author: %s\n", fallbackText(row.OwnerID, "(unknown)"))
279				if row.OwnerName != "" {
280					fmt.Fprintf(w, "Author Name: %s\n", row.OwnerName)
281				}
282				if row.OwnerEmail != "" {
283					fmt.Fprintf(w, "Author Email: %s\n", row.OwnerEmail)
284				}
285			}
286			if row.Branch != "" {
287				fmt.Fprintf(w, "Branch: %s\n", row.Branch)
288			}
289			fmt.Fprintf(w, "Checkpoint: %s\n", row.CheckpointID)
290			fmt.Fprintf(w, "Summary: %s  Facets: %s\n", yesNo(row.HasSummary), yesNo(row.HasFacets))
291	
292			if row.HasSummary {
293				fmt.Fprintln(w, "Intent:")
294				fmt.Fprintf(w, "  %s\n", fallbackText(row.Intent, "No summary cached"))
295				fmt.Fprintln(w, "Outcome:")
296				fmt.Fprintf(w, "  %s\n", fallbackText(row.Outcome, "No summary cached"))
297				renderStringListSection(w, "Friction", row.Friction, "No friction recorded")
298				renderLearningSection(w, row.Learnings)
299				renderStringListSection(w, "Implementation Rationale", row.ImplementationRationale, "No implementation rationale recorded")
300				renderStringListSection(w, "Tradeoffs", row.Tradeoffs, "No tradeoffs recorded")
301				renderStringListSection(w, "Codebase Patterns", row.CodebasePatterns, "No codebase patterns recorded")
302			} else {
303				fmt.Fprintln(w, "No summary cached")
304			}
305	
306			renderFacetSections(w, row.Facets, row.HasFacets)
307		}
308	}
