467	// generateForSession generates summary and facets for a single session on demand.
468	// It opens its own database connection and checkpoint store.
469	func generateForSession(ctx context.Context, row insightsdb.SessionRow) (insightsdb.SessionRow, error) {
470		repo, err := openRepository(ctx)
471		if err != nil {
472			return row, fmt.Errorf("open repository: %w", err)
473		}
474		store := checkpoint.NewGitStore(repo)
475	
476		cpID, err := checkpointid.NewCheckpointID(row.CheckpointID)
477		if err != nil {
478			return row, fmt.Errorf("invalid checkpoint ID: %w", err)
479		}
480	
481		content, err := store.ReadSessionContent(ctx, cpID, row.SessionIndex)
482		if err != nil {
483			return row, fmt.Errorf("read session content: %w", err)
484		}
485		if len(content.Transcript) == 0 {
486			return row, fmt.Errorf("empty transcript for checkpoint %s", row.CheckpointID)
487		}
488	
489		condensed, err := summarize.BuildCondensedTranscriptFromBytes(content.Transcript, content.Metadata.Agent)
490		if err != nil {
491			return row, fmt.Errorf("condense transcript: %w", err)
492		}
493		if len(condensed) == 0 {
494			return row, fmt.Errorf("condensed transcript empty for checkpoint %s", row.CheckpointID)
495		}
496	
497		input := summarize.Input{
498			Transcript:   condensed,
499			FilesTouched: row.FilesTouched,
500		}
501	
502		// Generate summary.
503		gen := &summarize.ClaudeGenerator{}
504		summary, genErr := gen.Generate(ctx, input)
505		if genErr != nil {
506			logging.Debug(ctx, "generateForSession: summary generation failed",
507				"checkpoint_id", row.CheckpointID, "error", genErr)
508		}
509		if summary != nil {
510			content.Metadata.Summary = summary
511			row = metadataToSessionRow(row.CheckpointID, row.SessionIndex, &content.Metadata)
512		}
513	
514		// Extract facets.
515		formatted := summarize.FormatCondensedTranscript(input)
516		extractor := &facets.Extractor{Runner: &llmcli.Runner{}}
517		facetResult, _, extractErr := extractor.Extract(ctx, formatted)
518		if extractErr != nil {
519			logging.Debug(ctx, "generateForSession: facet extraction failed",
520				"checkpoint_id", row.CheckpointID, "error", extractErr)
521		}
522		if facetResult != nil {
523			row.Facets = *facetResult
524			row.HasFacets = true
525		}
526	
527		// Persist to database.
528		worktreeRoot, err := paths.WorktreeRoot(ctx)
529		if err != nil {
530			return row, fmt.Errorf("find worktree root: %w", err)
531		}
532		idb, err := insightsdb.Open(filepath.Join(worktreeRoot, paths.EntireDir, "insights.db"))
533		if err != nil {
534			return row, fmt.Errorf("open insights db: %w", err)
535		}
536		defer func() { _ = idb.Close() }()
537	
538		if row.HasSummary {
539			if updateErr := idb.UpdateSessionSummary(ctx, row); updateErr != nil {
540				return row, fmt.Errorf("save summary: %w", updateErr)
541			}
542		}
543		if row.HasFacets {
544			if updateErr := idb.UpdateSessionFacets(ctx, row); updateErr != nil {
545				return row, fmt.Errorf("save facets: %w", updateErr)
546			}
547		}
548	
549		// Return partial success even if one phase failed.
550		if genErr != nil && extractErr != nil {
551			return row, fmt.Errorf("summary: %w; facets: %w", genErr, extractErr)
552		}
553		return row, nil
554	}
